```csharp
using System;
using System.IO;
using System.Linq;
using System.Numerics;
using System.Globalization;
using System.Collections.Generic;
using System.Text.Json;
using PicoGK;
public static class Program
{
public static void Main(string[] arguments)
{
if (arguments.Length != 2) throw new ArgumentException("input output-directory");
if (Directory.Exists(arguments[1]) && Directory.EnumerateFileSystemEntries(arguments[1]).Any())
throw new IOException("Use an empty output directory.");
Directory.CreateDirectory(arguments[1]);
using PicoGK.Library lib = new PicoGK.Library(0.2f);
PicoGK.IImplicit field = new Crack(new Vector3(0.20000f,-0.80000f,0.40000f),2.94000f,0.28000f);
PicoGK.BBox3 domain = new PicoGK.BBox3(new Vector3(-8),new Vector3(8));
using PicoGK.Voxels body = new PicoGK.Voxels(lib,field,domain);
body.Offset(0.62000f); body.Offset(-0.62000f);
WriteArtifacts(body, arguments[1], lib);
}
private static void WriteArtifacts(PicoGK.Voxels body, string output, PicoGK.Library lib)
{
body.CalculateProperties(out float volume, out PicoGK.BBox3 measured);
if (!float.IsFinite(volume) || volume <= 0) throw new InvalidDataException("Empty body.");
body.SaveToVdbFile(Path.Combine(output, "part.vdb"));
using PicoGK.Mesh raw = new PicoGK.Mesh(body);
using PicoGK.Mesh clean = new PicoGK.Mesh(lib);
for (int i = 0; i < raw.nTriangleCount(); i++)
{
raw.GetTriangle(i, out Vector3 a, out Vector3 b, out Vector3 c);
double ux = (double)b.X-a.X, uy = (double)b.Y-a.Y, uz = (double)b.Z-a.Z;
double vx = (double)c.X-a.X, vy = (double)c.Y-a.Y, vz = (double)c.Z-a.Z;
if (uy*vz != uz*vy || uz*vx != ux*vz || ux*vy != uy*vx) clean.nAddTriangle(a,b,c);
}
if (clean.nTriangleCount() == 0) throw new InvalidDataException("Empty surface.");
clean.SaveToStlFile(Path.Combine(output, "part.stl"), PicoGK.Mesh.EStlUnit.MM);
File.WriteAllText(Path.Combine(output, "report.json"), JsonSerializer.Serialize(new {
status="geometric_candidate", qualification="geometry_only", manufacturing_authorized=false }));
}
public sealed class Crack : PicoGK.IImplicit
{
private readonly Vector3 centre;
private readonly float half;
private readonly float gap;
public Crack(Vector3 centre, float half, float gap) { this.centre=centre; this.half=half; this.gap=gap; }
public float fSignedDistance(in Vector3 p)
{
Vector3 q = Vector3.Abs(p-centre);
return MathF.Max(MathF.Max(q.X,MathF.Max(q.Y,q.Z))-half,gap/2-q.X);
}
}
}
